   yield return new WaitForSecondsRealtime(.35f);
   var vehicle=game.Vehicle.GetComponentInChildren<VanArt>();Check(vehicle!=null,"Actual driving van supplies the model inspection");CheckNativeGlass(vehicle);CheckNativeMoldedSurface(vehicle);var support=game.Vehicle.GetComponent<BoxCollider>();Check(support!=null,"Actual service van retains its driving support collider");int tires=0;
   foreach(var filter in vehicle.GetComponentsInChildren<MeshFilter>(true))if(filter.name=="Rubber tire")
   {
    tires++;float bottom=float.PositiveInfinity;foreach(var point in filter.sharedMesh.vertices)bottom=Mathf.Min(bottom,filter.transform.TransformPoint(point).y);
    Check(Mathf.Abs(bottom-support.bounds.min.y)<.012f,"Actual road tire aligns with the production collider bottom "+tires);
    bool grounded=false;foreach(var hit in Physics.RaycastAll(filter.transform.position+Vector3.up,Vector3.down,3))if(hit.collider.name=="Continuous driveable ground")grounded=Mathf.Abs(bottom-hit.point.y)<.035f;
    Check(grounded,"Actual road tire meets the driven avenue support "+tires);
   }
   var retained=new HashSet<Mesh>();var finishes=new HashSet<Material>();int retainedVertices=0,activeRenderers=0;bool validBuffers=true;
   foreach(var filter in vehicle.GetComponentsInChildren<MeshFilter>(true)){if(filter.sharedMesh==null){validBuffers=false;continue;}if(retained.Add(filter.sharedMesh))retainedVertices+=filter.sharedMesh.vertexCount;}
   foreach(var renderer in vehicle.GetComponentsInChildren<MeshRenderer>(true)){if(renderer.enabled)activeRenderers++;if(renderer.sharedMaterial!=null&&renderer.sharedMaterial.name.StartsWith("Van",StringComparison.Ordinal))finishes.Add(renderer.sharedMaterial);}
   Check(validBuffers,"Copied detail buffers/components are disposed after batching without dangling mesh filters");Check(retainedVertices<70000&&activeRenderers<=32&&finishes.Count==9,"Actual driving model retains budget: "+retainedVertices+" vertices / "+activeRenderers+" renderers / "+finishes.Count+" materials");
   Check(tires==4,"Actual ground alignment covers all four road tires");Check(vehicle.CapturedStreetReflection,"Production van captures the actual street reflection once");Check(GameObject.Find("One-time van street capture")==null,"One-time reflection camera is disposed before driving");var origin=vehicle.transform.position;var rotation=vehicle.transform.rotation;int cash=game.Profile.Cash;var host=new GameObject("QA actual van inspection camera",typeof(Camera));var cam=host.GetComponent<Camera>();cam.CopyFrom(Camera.main);cam.enabled=false;cam.fieldOfView=37;cam.aspect=4f/3f;var target=new RenderTexture(1024,768,24,RenderTextureFormat.ARGB32){name="Actual van inspection",antiAliasing=2};target.Create();cam.targetTexture=target;var previous=RenderTexture.active;var hashes=new HashSet<int>();
   try
   {
    var eyes=new[]{new Vector3(4.4f,2.8f,6.5f),new Vector3(4.2f,2.8f,-6.4f),new Vector3(0,2.3f,-7.2f),new Vector3(7.4f,2.4f,0),new Vector3(-2.7f,2.45f,3.7f),new Vector3(2.4f,1.7f,4.3f),new Vector3(2.5f,.90f,2.0f)};var names=new[]{"van-front-three-quarter","van-rear-three-quarter","van-rear","van-side","van-cabin","van-front-detail","van-wheel-detail"};
    for(int view=0;view<eyes.Length;view++)
    {
     cam.transform.position=vehicle.transform.TransformPoint(eyes[view]);cam.transform.LookAt(vehicle.transform.TransformPoint(view==5?new Vector3(0,.83f,1.86f):view==6?new Vector3(.81f,.38f,1.38f):view==4?new Vector3(-.15f,1.42f,.65f):new Vector3(0,1.25f,0)));cam.fieldOfView=view>=4?30:37;cam.Render();scenePixels.Remove(target);hashes.Add(RenderedFingerprint(target));var pixels=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);
     try{RenderTexture.active=target;pixels.ReadPixels(new Rect(0,0,target.width,target.height),0,0);pixels.Apply();File.WriteAllBytes(Path.Combine(output,names[view]+".png"),pixels.EncodeToPNG());}finally{Destroy(pixels);}
    }
    Check(hashes.Count==7,"Seven different actual van, cabin, front and wheel inspection views");Check(vehicle.transform.position==origin&&vehicle.transform.rotation==rotation&&game.Profile.Cash==cash,"Inspection camera never moves the van or changes company authority");
   }
