   var target=new RenderTexture(128,128,24,RenderTextureFormat.ARGB32);var pixels=new Texture2D(128,128,TextureFormat.RGB24,false);var previous=RenderTexture.active;bool enabled=city.Probe.enabled;
   try
   {
