ect.Find("ScrollViewport").GetComponent<ScrollRect>();companyScroll.verticalNormalizedPosition=0;yield return null;PresentationChecks();yield return Capture("showcase-"+game.Profile.Language+"-dashboard-sections");game.Hud.Close();for(int tab=0;tab<8;tab++){game.Hud.ShowPage(tab);yield return null;Sizes();PresentationChecks();yield return Capture("showcase-"+game.Profile.Language+"-"+tab);game.Hud.Close();}}game.Hud.ShowPage(6);yield return null;var settingsScroll=GameObject.Find("ScrollViewport").GetComponent<ScrollRect>();settingsScroll.verticalNormalizedPosition=0;yield return null;yield return Capture("showcase-guide-replay-entry");game.Hud.Close();yield return Poses();}
